<template><section class="workspace-page constellation-page"><PageHeader title="让知识，彼此相连。" description="从一份原文、一次练习，到一条自己的学习路线。" eyebrow="我的知识星图"><template #actions><RouterLink to="/library" class="m-btn m-btn--ghost m-btn--sm"><BookOpen :size="17"/>知识库</RouterLink></template></PageHeader><nav class="workspace-segments" aria-label="星图视图"><RouterLink v-for="tab in tabs" :key="tab.id" :to="{path:'/atlas',query:{view:tab.id}}" :aria-current="view===tab.id?'page':undefined">{{ tab.title }}</RouterLink></nav><div v-if="store.error" class="m-error" role="alert">{{ store.error }}<button class="m-btn m-btn--ghost m-btn--sm" @click="store.refresh">重新读取</button></div><p v-if="store.evidenceError" class="m-error" role="alert">{{ store.evidenceError }}</p><div class="constellation-context"><label class="m-field"><span>{{ view==='network'?'资料与路径范围':'目标范围' }}</span><select v-if="view==='network'" v-model="networkScope" class="m-input"><option value="all">全部已保存知识</option><option value="path">当前学习路径</option><option value="notes">资料与双链笔记</option><option v-for="material in store.workspace?.materials||[]" :key="material.id" :value="material.id">{{ material.title }}</option></select><select v-else v-model="goalId" class="m-input"><option value="">当前保存的学习路径</option><option v-for="goal in store.workspace?.goals||[]" :key="goal.id" :value="goal.id">{{ goal.title }}</option></select></label><RouterLink :to="{path:'/agent',query:{...(goalId?{goal:goalId}:{})}}" class="workspace-text-action"><Sparkles :size="16"/>让星枢提出下一步</RouterLink></div><div class="constellation-content"><DashboardWidget :title="tabs.find(t=>t.id===view)!.title" :source="view==='network'?'来源：已保存路径、原文链接与真实练习记录':view==='metro'?'来源：保存的阶段顺序或已确认任务清单':'来源：可归因的服务器作答记录'">
<KnowledgeGraph v-if="view==='network'" :nodes="nodes" :edges="edges" :selected="selectedId" @select="selectNode"/>
<LearningMetroMap v-else-if="view==='metro'" :stages="stages" @select="selectStage"/>
<template v-else><p v-if="goalId" class="workspace-caption">当前练习接口未提供目标与能力的归属，筛选此目标时不混入其他课程证据。请查看当前保存路径，或先完善目标关联。</p><AbilityMap :abilities="goalId?[]:abilities" @select="selectAbility"/></template>
</DashboardWidget><aside v-if="selected" class="constellation-selected"><DashboardWidget :title="selected.title" :source="selected.kind==='note'?'当前账号私有资料':'实际路径与可读取的完成记录'"><span class="m-badge m-badge--info">{{ evidenceStates[selected.state] }}</span><p class="selected-description">{{ selected.description }}</p><template v-if="selected.topicId"><div v-if="store.topicEvidence[selected.topicId]" class="selected-evidence"><b>{{ store.topicEvidence[selected.topicId]!.answers }} 条作答证据</b><p>答对 {{ store.topicEvidence[selected.topicId]!.correct }} 题。单次表现不等于已掌握。</p></div><p v-else class="workspace-caption">没有此知识点可归因的已完成练习，不显示掌握百分比。</p><div class="workspace-actions"><RouterLink :to="{path:'/tutor',query:{topic:selected.topicId,name:selected.title}}" class="m-btn m-btn--primary m-btn--sm">让导师讲一讲</RouterLink><button class="m-btn m-btn--ghost m-btn--sm" :disabled="busy" @click="practice(selected.topicId)">练习这个知识点</button><RouterLink :to="{path:'/agent',query:{topicName:selected.title}}" class="workspace-text-action">让星枢安排复习 →</RouterLink></div><h3>相关错题</h3><RouterLink v-for="row in store.reviews.filter(r=>r.exercise.topicId===selected!.topicId)" :key="row.exercise.id" to="/review" class="constellation-related">{{ row.exercise.knowledgePoint }} →</RouterLink></template><template v-if="selected.materialId"><p v-for="section in selectedMaterial?.sections.slice(0,2)||[]" :key="section.id" class="source-excerpt">{{ section.text }}</p><div class="workspace-actions"><RouterLink :to="{path:'/library',query:{material:selected.materialId}}" class="m-btn m-btn--primary m-btn--sm">原文与来源问答</RouterLink><RouterLink :to="{path:'/agent',query:{material:selected.materialId,kind:'materials'}}" class="m-btn m-btn--ghost m-btn--sm">整理复习包</RouterLink></div><h3>反向链接</h3><p v-if="!backlinks.length" class="workspace-caption">暂时没有已解析的反向链接。</p><button v-for="linked in backlinks" :key="linked.id" class="workspace-text-action" @click="selectNode(linked)">{{ linked.title }} →</button><h3>关联笔记</h3><p v-for="note in store.workspace?.notes.filter(n=>n.materialId===selected!.materialId)||[]" :key="note.id" class="source-excerpt">{{ note.title }}：{{ note.content.slice(0,180) }}</p><button v-if="metadata" class="workspace-text-action" @click="downloadText(metadata.path.split('/').slice(-1)[0]!,metadata.raw)">导出原始 Markdown →</button></template><template v-if="selected.taskId"><RouterLink to="/learn?tab=plan" class="m-btn m-btn--primary m-btn--sm">查看目标任务与计划</RouterLink></template><p v-if="actionError" class="m-error" role="alert">{{ actionError }}</p></DashboardWidget></aside></div><p v-if="unresolvedCount&&view==='network'" class="workspace-caption">有 {{ unresolvedCount }} 个链接目标尚未导入或同名不唯一，未伪造对应笔记。</p><AppDialog v-model="abilityOpen" :title="abilitySelected?.title||'能力证据'"><template v-if="abilitySelected"><p>关联 {{ abilitySelected.topics }} 个路径知识点，已读取 {{ abilitySelected.answers }} 条作答证据。</p><p v-if="!abilitySelected.answers">尚无足够证据。完成相关练习后，可查看题目级记录；这里不会显示自评推算的精确能力分数。</p><p v-else>答对 {{ abilitySelected.correct }} / {{ abilitySelected.answers }} 题，仅代表这些已保存题目的表现。</p><RouterLink to="/learn?tab=practice" class="m-btn m-btn--primary m-btn--sm">继续练习并补充证据</RouterLink></template></AppDialog></section></template>
<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { BookOpen,Sparkles } from 'lucide-vue-next'
import { useLearningWorkspace } from '@/mobile/stores/learning-workspace'
import { evidenceStates,type GraphEdge,type GraphNode } from '@/mobile/domain/knowledge-graph'
import { resolveVaultLinks } from '@/mobile/domain/markdown-vault'
import { createStudySession } from '@/mobile/data/study'
import { downloadText } from '@/mobile/data/workspace'
import PageHeader from '@/mobile/components/PageHeader.vue'
import DashboardWidget from '@/mobile/components/DashboardWidget.vue'
import KnowledgeGraph from '@/mobile/components/KnowledgeGraph.vue'
import LearningMetroMap,{type MetroStage} from '@/mobile/components/LearningMetroMap.vue'
import AbilityMap from '@/mobile/components/AbilityMap.vue'
import AppDialog from '@/mobile/components/AppDialog.vue'
const store=useLearningWorkspace(),route=useRoute(),router=useRouter(),networkScope=ref('all'),goalId=ref(''),selectedId=ref(''),busy=ref(false),actionError=ref(''),abilityOpen=ref(false),abilityId=ref(''),tabs=[{id:'network',title:'知识网络'},{id:'metro',title:'学习轨迹'},{id:'ability',title:'能力图谱'}]
const view=computed(()=>tabs.some(t=>t.id===route.query.view)?String(route.query.view):'network'),validVault=computed(()=>Object.values(store.local.vault).filter(v=>store.workspace?.materials.some(m=>m.id===v.materialId))),linkModel=computed(()=>resolveVaultLinks(validVault.value)),unresolvedCount=computed(()=>linkModel.value.unresolved.length)
const nodes=computed<GraphNode[]>(()=>{
 const topics:GraphNode[]=networkScope.value==='notes'||!['all','path'].includes(networkScope.value)?[]:store.path?.phases.flatMap(phase=>phase.topics.map(topic=>({id:`topic:${topic.id}`,title:topic.name,kind:'topic' as const,state:store.reviews.some(r=>r.exercise.topicId===topic.id)?'review' as const:store.topicEvidence[topic.id]?'evidence' as const:store.workspace?.focus.some(f=>['running','paused'].includes(f.status)&&store.local.focusLinks[f.id]?.topicId===topic.id)?'learning' as const:'unstarted' as const,description:`来自「${phase.name}」阶段。节点名称由保存的路径提供，状态取自练习证据，不使用路径估计百分比。`,topicId:topic.id,phaseId:phase.id})))||[]
 const materials:GraphNode[]=networkScope.value==='path'?[]:store.workspace?.materials.filter(m=>['all','notes'].includes(networkScope.value)||m.id===networkScope.value).map(material=>({id:`material:${material.id}`,title:store.local.vault[material.id]?.title||material.title,kind:'note' as const,state:'unstarted' as const,description:material.sections.length?`${material.sections.length} 段可定位原文；保存资料不代表已掌握。`:'当前没有可检索文字，请先补充转录。',materialId:material.id,tags:material.tags}))||[]
 return [...topics,...materials]
})
const edges=computed<GraphEdge[]>(()=>{const result:GraphEdge[]=linkModel.value.edges.flatMap(edge=>{const a=validVault.value.find(v=>v.path===edge.from),b=validVault.value.find(v=>v.path===edge.to);return a&&b?[{from:`material:${a.materialId}`,to:`material:${b.materialId}`,label:'原文中的双链 / 相对链接'}]:[]});for(const phase of store.path?.phases||[]){for(let i=1;i<phase.topics.length;i++)result.push({from:`topic:${phase.topics[i-1]!.id}`,to:`topic:${phase.topics[i]!.id}`,label:'同一保存阶段，不代表已核验前置依赖'})}return result})
const selected=computed(()=>nodes.value.find(n=>n.id===selectedId.value)||null),selectedMaterial=computed(()=>store.workspace?.materials.find(m=>m.id===selected.value?.materialId)),metadata=computed(()=>selected.value?.materialId?store.local.vault[selected.value.materialId]:null),backlinks=computed(()=>{if(!metadata.value)return[];const paths=linkModel.value.backlinks(metadata.value.path);return nodes.value.filter(n=>n.materialId&&paths.includes(store.local.vault[n.materialId]?.path||''))})
const stages=computed<MetroStage[]>(()=>goalId.value?store.workspace?.tasks.filter(t=>t.status==='completed'&&t.goalId===goalId.value).map(task=>({id:task.id,title:task.prompt,state:!!task.checklist?.length&&(task.checklist||[]).every(i=>i.done)?'done':'learning',stateLabel:!!task.checklist?.length&&(task.checklist||[]).every(i=>i.done)?'用户确认完成':'待完成已确认清单',details:'站点来自一次已确认的任务计划。完成状态为用户手动确认，不是能力评估。',completed:(task.checklist||[]).filter(i=>i.done).length,total:task.checklist?.length||0}))||[]:store.path?.phases.map(phase=>{const evidence=phase.topics.reduce((n,t)=>n+(store.topicEvidence[t.id]?.answers||0),0),review=store.reviews.some(r=>phase.topics.some(t=>t.id===r.exercise.topicId));return{id:phase.id,title:phase.name,state:review?'review':evidence?'evidence':'unstarted',stateLabel:review?'该阶段有错题待回忆':evidence?`${evidence} 条已完成作答证据`:'尚无足够证据',details:`包含 ${phase.topics.length} 个路径知识点。阶段顺序来自保存路径，前置关系尚未单独核验。`,completed:null,total:null}})||[])
const abilities=computed(()=>store.path?.phases.map(phase=>({id:phase.id,title:phase.name,topics:phase.topics.length,answers:phase.topics.reduce((n,t)=>n+(store.topicEvidence[t.id]?.answers||0),0),correct:phase.topics.reduce((n,t)=>n+(store.topicEvidence[t.id]?.correct||0),0)}))||[]),abilitySelected=computed(()=>abilities.value.find(a=>a.id===abilityId.value))
onMounted(()=>store.refresh())
function selectNode(node:GraphNode){selectedId.value=node.id}
function selectStage(id:string){if(goalId.value){router.push('/learn?tab=plan');return};const phase=store.path?.phases.find(p=>p.id===id);networkScope.value='path';selectedId.value=phase?.topics[0]?`topic:${phase.topics[0].id}`:'';router.replace({path:'/atlas',query:{view:'network'}})}
function selectAbility(id:string){abilityId.value=id;abilityOpen.value=true}
async function practice(topicId:string){busy.value=true;try{const result=await createStudySession([topicId],3);if('error'in result)throw new Error(result.message);await router.push(`/study/session/${result.session.id}`)}catch(e){actionError.value=e instanceof Error?e.message:'创建失败'}finally{busy.value=false}}
</script>
<style scoped>.constellation-context{display:flex;gap:16px;align-items:flex-end;justify-content:space-between;flex-wrap:wrap;margin-bottom:22px}.constellation-context .m-field{flex:1;min-width:200px;max-width:420px}.constellation-context>a{display:flex;gap:7px;align-items:center}.constellation-content{display:grid;gap:20px}.constellation-selected h3{font-size:16px;margin:22px 0 12px}.selected-description{font-size:14px;line-height:1.9;color:var(--m-text-dim)}.selected-evidence{padding:14px;border:1px solid var(--m-success);border-radius:14px;background:var(--m-success-soft);font-size:14px}.selected-evidence p{font-size:13px;line-height:1.8;color:var(--m-text-dim)}.source-excerpt{font-size:14px;line-height:1.9;color:var(--m-text-dim);padding:12px 0;border-bottom:1px solid var(--m-border);white-space:pre-wrap}.constellation-related{display:block;min-height:44px;color:var(--m-primary);font-size:14px;text-decoration:none}@media(min-width:1150px){.constellation-content:has(.constellation-selected){grid-template-columns:minmax(0,1.5fr) minmax(280px,1fr)}.constellation-selected{align-self:start;position:sticky;top:96px}}
</style>
